// Worker bundles: each worker the app starts, and each module a worker imports
// by URL, built into one self-contained file whose name is the SHA-256 of its
// bytes.
//
// A page reaches its own modules through its import map, which names every
// module's bytes (`?v=`), so a deploy cannot pair a module cached from one
// build with one of the next. No engine gives a worker an import map, so a
// worker started from its source asks for every import by plain path, and a
// host that caches by path (GitHub Pages answers each file with
// `max-age=600`) can hand it a previous build's file. A bundle is one request
// at an address no other build uses, so it cannot be split that way.
//
// `generate-web-asset-inventory.mjs` builds them with every run, before the
// inventory, which then lists them; `--check` refuses a tree whose bundles are
// not exactly what the sources build. They are written to `assets/workers/`,
// a folder of nothing but what this writes, outside the sources under
// `assets/js/` (whose contracts read every file there). Beside them it writes
// `assets/workers/scripts.js`, one function per entry returning the URL to
// start it from: the bundle on a deployed site, the source on this machine
// (`assets/js/workers/worker-script.js`), so development needs no build.
//
// esbuild is pinned in package.json: the same version and options give the
// same bytes on every platform, which is what lets `--check` compare them.

import { createHash } from 'node:crypto';
import { mkdir, readFile, readdir, unlink } from 'node:fs/promises';
import { dirname, join, posix, resolve } from 'node:path';

export const WORKERS_DIR = 'assets/workers';
export const WORKER_SCRIPTS_PATH = `${WORKERS_DIR}/scripts.js`;
const WORKER_SCRIPT_HELPER = '../js/workers/worker-script.js';

/**
 * Every worker entry: a worker the app starts, or a module a worker imports by
 * URL (`runOnDecodeWorker`'s task modules). `name` is the function
 * `scripts.js` exports for it, with `Script` appended.
 */
export const WORKER_ENTRIES = Object.freeze([
  { name: 'annDataReaderWorker', source: 'assets/js/data/anndata-reader-worker.js' },
  { name: 'benchmarkGenerationWorker', source: 'assets/js/app/ui/modules/benchmark/generation-worker.js' },
  { name: 'dataWorker', source: 'assets/js/app/analysis/compute/data-worker.js' },
  { name: 'decodeWorker', source: 'assets/js/formats/io/decode-worker.js' },
  { name: 'figureExportWorker', source: 'assets/js/app/ui/modules/figure-export/utils/figure-export-worker.js' },
  { name: 'gunzipWorker', source: 'assets/js/formats/rds/gunzip-worker.js' },
  { name: 'matrixMarketEntries', source: 'assets/js/formats/text/matrix-market-entries.js' },
  { name: 'pointRasterWorker', source: 'assets/js/app/analysis/plots/point-raster-worker.js' },
  { name: 'spatialTreeWorker', source: 'assets/js/rendering/high-perf/spatial-tree-worker.js' },
  { name: 'subsetEntries', source: 'assets/js/data/anndata/subset-entries.js' },
].map(entry => Object.freeze(entry)));

const BUNDLE_VERSION_LENGTH = 12;
/** A bundle or its source map, as the generator names them. */
export const BUNDLE_FILE = /^([a-z0-9-]+)\.([0-9a-f]{12})\.js(\.map)?$/;

function stemOf(source) {
  return posix.basename(source, '.js');
}

function relativeToWorkers(path) {
  const relative = posix.relative(WORKERS_DIR, path);
  return relative.startsWith('../') ? relative : `./${relative}`;
}

/** `scripts.js` for the given bundle file names, by entry name. */
export function renderWorkerScripts(bundleNames) {
  const lines = [
    '// Generated by scripts/generate-web-asset-inventory.mjs (WORKER_ENTRIES in',
    '// scripts/build-worker-bundles.mjs); do not edit. One function per worker',
    '// entry: the URL to start it from, its source on this machine and its',
    '// bundle anywhere else (assets/js/workers/worker-script.js).',
    `import { workerScript } from '${WORKER_SCRIPT_HELPER}';`,
    '',
  ];
  for (const { name, source } of WORKER_ENTRIES) {
    lines.push(
      `/** @returns {URL} ${source} */`,
      `export const ${name}Script = () => workerScript(import.meta.url, `
        + `'${relativeToWorkers(source)}', './${bundleNames.get(name)}');`,
    );
  }
  return Buffer.from(`${lines.join('\n')}\n`, 'utf8');
}

function placeholderNames() {
  return new Map(WORKER_ENTRIES.map(({ name, source }) => [
    name, `${stemOf(source)}.${'0'.repeat(BUNDLE_VERSION_LENGTH)}.js`,
  ]));
}

/** The code of each module of a bundle, by the path comment esbuild heads it with. */
function bundleSections(code) {
  const sections = new Map();
  let current = '';
  for (const line of code.split('\n')) {
    const header = /^\/\/ (assets\/\S+\.js)$/.exec(line);
    if (header !== null) {
      current = header[1];
      continue;
    }
    sections.set(current, `${sections.get(current) ?? ''}${line}\n`);
  }
  return sections;
}

async function buildOne({ esbuild, rootDir, entry, scriptsText }) {
  const scriptsPath = resolve(rootDir, ...WORKER_SCRIPTS_PATH.split('/'));
  const result = await esbuild.build({
    absWorkingDir: rootDir,
    entryPoints: [entry.source],
    bundle: true,
    format: 'esm',
    platform: 'browser',
    // No target: the code ships as written, as the sources do.
    charset: 'utf8',
    sourcemap: 'external',
    sourcesContent: false,
    outdir: WORKERS_DIR,
    entryNames: '[name]',
    write: false,
    metafile: true,
    logLevel: 'silent',
    plugins: [{
      name: 'cellucid-worker-scripts',
      setup(build) {
        // The bundles are built against the `scripts.js` of this pass, which
        // names the bundles of the previous one (and need not exist on disk).
        build.onResolve({ filter: /(^|\/)scripts\.js$/ }, args => (
          resolve(args.resolveDir, args.path) === scriptsPath ? { path: scriptsPath } : undefined
        ));
        // Its own import, resolved here: its folder may not exist yet.
        build.onResolve({ filter: /^\.\.?\// }, args => (
          args.importer === scriptsPath ? { path: resolve(dirname(scriptsPath), args.path) } : undefined
        ));
        build.onLoad({ filter: /[\\/]workers[\\/]scripts\.js$/ }, args => (
          resolve(args.path) === scriptsPath
            ? { contents: scriptsText, loader: 'js', resolveDir: dirname(scriptsPath) }
            : undefined
        ));
      },
    }],
  });
  if (result.warnings.length > 0 || result.errors.length > 0) {
    const messages = await esbuild.formatMessages(
      [...result.errors, ...result.warnings],
      { kind: 'warning' }
    );
    throw new Error(`Bundling ${entry.source} reported:\n${messages.join('\n')}`);
  }
  const inputs = Object.keys(result.metafile.inputs).sort();
  for (const input of inputs) {
    if (!input.startsWith('assets/js/') && input !== WORKER_SCRIPTS_PATH) {
      throw new Error(`${entry.source} imports ${input}, which is not shipped under assets/js/.`);
    }
  }
  const code = result.outputFiles.find(file => file.path.endsWith('.js')).text;
  const map = result.outputFiles.find(file => file.path.endsWith('.js.map')).contents;
  // A module of the graph that reads import.meta would resolve against the
  // bundle's address; only `scripts.js` may, and it lives beside the bundles.
  for (const [section, text] of bundleSections(code)) {
    if (section !== WORKER_SCRIPTS_PATH && /\bimport\.meta\b/.test(text)) {
      throw new Error(
        `${section || entry.source} reads import.meta, which in a bundle names the bundle: `
          + `start workers and name modules by URL through ${WORKER_SCRIPTS_PATH}.`
      );
    }
  }
  return { code, map: Buffer.from(map), inputs };
}

/**
 * Build every worker entry. Bundles that start other workers (the AnnData
 * reader starts decode and gunzip workers) carry those workers' bundle names,
 * so the names are settled by rebuilding until they stop changing; a bundle
 * that named itself never would, and is refused.
 *
 * @param {{ rootDir: string }} options
 * @returns {Promise<{ files: Map<string, Buffer>, bundles: Array<{ name: string, source: string, path: string, inputs: string[] }> }>}
 */
export async function buildWorkerBundles({ rootDir }) {
  const esbuild = await import('esbuild');
  const exactRoot = resolve(rootDir);
  let names = placeholderNames();
  for (let pass = 0; pass <= WORKER_ENTRIES.length + 1; pass += 1) {
    const scriptsText = renderWorkerScripts(names).toString('utf8');
    const built = [];
    for (const entry of WORKER_ENTRIES) {
      built.push({ entry, ...(await buildOne({ esbuild, rootDir: exactRoot, entry, scriptsText })) });
    }
    const next = new Map(built.map(({ entry, code, map }) => {
      const version = createHash('sha256').update(code).update('\0').update(map)
        .digest('hex').slice(0, BUNDLE_VERSION_LENGTH);
      return [entry.name, `${stemOf(entry.source)}.${version}.js`];
    }));
    if ([...next].every(([name, file]) => names.get(name) === file)) {
      const files = new Map([[WORKER_SCRIPTS_PATH, Buffer.from(scriptsText, 'utf8')]]);
      const bundles = [];
      for (const { entry, code, map, inputs } of built) {
        const file = next.get(entry.name);
        const path = `${WORKERS_DIR}/${file}`;
        files.set(path, Buffer.from(`${code}//# sourceMappingURL=${file}.map\n`, 'utf8'));
        files.set(`${path}.map`, map);
        bundles.push({ name: entry.name, source: entry.source, path, inputs });
      }
      return { files, bundles };
    }
    names = next;
  }
  throw new Error('A worker bundle names its own bundle, so no build of it is final: a worker cannot start itself.');
}

async function workerFilesOnDisk(rootDir) {
  const directory = join(resolve(rootDir), ...WORKERS_DIR.split('/'));
  let names;
  try {
    names = await readdir(directory);
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
  return names.map(name => `${WORKERS_DIR}/${name}`);
}

/**
 * The worker files that are not what the sources build: each expected file
 * that is missing or differs, and each file of the folder that no entry
 * builds (a previous build's bundle).
 *
 * @param {{ rootDir: string, built: { files: Map<string, Buffer> } }} options
 * @returns {Promise<string[]>}
 */
export async function staleWorkerFiles({ rootDir, built }) {
  const exactRoot = resolve(rootDir);
  const stale = [];
  for (const [path, bytes] of built.files) {
    let current = null;
    try {
      current = await readFile(join(exactRoot, ...path.split('/')));
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
    if (current === null || !current.equals(bytes)) stale.push(path);
  }
  for (const path of await workerFilesOnDisk(exactRoot)) {
    if (!built.files.has(path)) stale.push(path);
  }
  return stale.sort();
}

/**
 * Write the built worker files and remove every other file of the folder.
 *
 * @param {{ rootDir: string, built: { files: Map<string, Buffer> }, write: (absolutePath: string, bytes: Buffer) => Promise<void> }} options
 */
export async function writeWorkerBundles({ rootDir, built, write }) {
  const exactRoot = resolve(rootDir);
  await mkdir(join(exactRoot, ...WORKERS_DIR.split('/')), { recursive: true });
  for (const path of await staleWorkerFiles({ rootDir: exactRoot, built })) {
    const absolutePath = join(exactRoot, ...path.split('/'));
    if (built.files.has(path)) {
      await write(absolutePath, built.files.get(path));
    } else {
      await unlink(absolutePath);
    }
  }
}
